def find_overlaps(bookings: list[Booking]) -> list[tuple[str, str]]:
    """Return every clashing pair as (id_a, id_b) with id_a < id_b, sorted.

    Two bookings clash when they are in the same room and their half-open
    intervals intersect. A booking fully inside a longer one clashes with it;
    a booking that ends exactly when another starts does not.
    """
    pairs: list[tuple[str, str]] = []

    by_room = {}
    for booking in bookings:
        if booking.room not in by_room:
            by_room[booking.room] = []
        by_room[booking.room].append(booking)

    for room_bookings in by_room.values():
        events = []
        for b in room_bookings:
            events.append((b.start, 0, b))
            events.append((b.end, 1, b))

        events.sort()

        active = {}
        for time, event_type, booking in events:
            if event_type == 0:
                for active_id in active:
                    a_id, b_id = booking.id, active_id
                    if a_id > b_id:
                        a_id, b_id = b_id, a_id
                    pairs.append((a_id, b_id))
                active[booking.id] = booking
            else:
                active.pop(booking.id, None)

    pairs.sort()
    return pairs

